begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();w uuid:=gen_random_uuid();guest uuid:=gen_random_uuid();r jsonb;s jsonb;room uuid;begin
 insert into auth.users(id,aud,role,email,is_anonymous) values(u,'authenticated','authenticated',u::text||'@example.invalid',false),(v,'authenticated','authenticated',v::text||'@example.invalid',false),(w,'authenticated','authenticated',w::text||'@example.invalid',false),(guest,'authenticated','authenticated',null,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 if has_function_privilege('anon','public.dy_multiplayer_join(text,integer,text,text,uuid)','execute') or has_table_privilege('authenticated','dy_private.mp_rooms','select') or has_function_privilege('authenticated','public.dy_multiplayer_cleanup()','execute') then raise exception 'privilege_leak';end if;
 perform public.dy_profile_set_with_avatar(p_avatar=>'yeti',p_handle=>'test_'||left(replace(u::text,'-',''),12),p_name=>'Player A',p_discoverable=>false,p_share=>false);
 begin perform public.dy_multiplayer_join('hex-fold',1);raise exception 'disabled_game_accepted';exception when others then if sqlerrm!='game_not_ready' then raise;end if;end;
 update dy_private.mp_games set enabled=true where id='hex-fold';
 begin perform public.dy_multiplayer_join('hex-fold',2);raise exception 'version_accepted';exception when others then if sqlerrm!='incompatible_client' then raise;end if;end;
 r:=public.dy_multiplayer_join('hex-fold',1);room:=(r->'room'->>'id')::uuid;
 if r->'room'->>'status'!='waiting' then raise exception 'not_waiting';end if;
 if public.dy_multiplayer_join('hex-fold',1)->'room'->>'id'!=room::text then raise exception 'retry_duplicated';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 perform public.dy_profile_set_with_avatar(p_avatar=>'fox',p_handle=>'test_'||left(replace(v::text,'-',''),12),p_name=>'Player B',p_discoverable=>false,p_share=>false);
 if public.dy_multiplayer_snapshot()->'room'!='null'::jsonb then raise exception 'room_leak';end if;
 r:=public.dy_multiplayer_join('hex-fold',1);
 if r->'room'->>'id'!=room::text or r->'room'->>'status'!='ready' or jsonb_array_length(r->'room'->'members')!=2 then raise exception 'match_failed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',w,'role','authenticated')::text,true);
 if public.dy_multiplayer_join('hex-fold',1)->'room'->>'id'=room::text then raise exception 'room_overfilled';end if;
 perform public.dy_multiplayer_leave();
 insert into public.dy_relations(low_id,high_id,requested_by,status) values(least(u,v),greatest(u,v),u,'accepted');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 if jsonb_array_length(public.dy_multiplayer_snapshot()->'friends')!=0 then raise exception 'presence_not_private_by_default';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 perform public.dy_multiplayer_privacy(true,false);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 s:=public.dy_multiplayer_snapshot();
 if jsonb_array_length(s->'friends')!=1 or s->'friends'->0->'coins'!='null'::jsonb then raise exception 'privacy_failed';end if;

 insert into public.dy_games(id,enabled) values('hex-fold',true) on conflict(id) do nothing;
 insert into public.dy_wallets(player_id,game_id,balance) values(v,'hex-fold',1234);
 update dy_private.mp_games set coin_sharing=true where id='hex-fold';
 if public.dy_multiplayer_snapshot()->'friends'->0->'coins'!='null'::jsonb then raise exception 'coins_shared_without_consent';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 perform public.dy_multiplayer_privacy(true,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 if public.dy_multiplayer_snapshot()->'friends'->0->>'coins' is distinct from '1234' then raise exception 'consented_coins_missing';end if;
 update dy_private.mp_people set last_seen=now()-interval '121 seconds' where player_id=v;
 if jsonb_array_length(public.dy_multiplayer_snapshot()->'friends')!=0 then raise exception 'stale_presence';end if;
 update dy_private.mp_people set last_seen=now() where player_id=v;
 insert into public.dy_blocks(player_id,target_id) values(v,u);
 if jsonb_array_length(public.dy_multiplayer_snapshot()->'friends')!=0 or public.dy_multiplayer_snapshot()->'room'!='null'::jsonb then raise exception 'block_bypassed';end if;
 perform public.dy_multiplayer_leave();
 delete from public.dy_blocks where player_id=v and target_id=u;
 r:=public.dy_multiplayer_join('hex-fold',1,'global','friends');room:=(r->'room'->>'id')::uuid;
 begin perform public.dy_multiplayer_invite(w);raise exception 'stranger_invited';exception when others then if sqlerrm!='invitation_unavailable' then raise;end if;end;
 perform public.dy_multiplayer_invite(v);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',w,'role','authenticated')::text,true);
 begin perform public.dy_multiplayer_join('hex-fold',1,'global','friends',room);raise exception 'private_room_intrusion';exception when others then if sqlerrm!='invitation_required' then raise;end if;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 perform public.dy_multiplayer_leave();
 if jsonb_array_length(public.dy_multiplayer_snapshot()->'invites')!=1 then raise exception 'invite_missing';end if;
 if public.dy_multiplayer_join('hex-fold',1,'global','friends',room)->'room'->>'status'!='ready' then raise exception 'friend_join_failed';end if;
 update dy_private.mp_members set expires_at=now()-interval '1 second' where player_id=u;
 if public.dy_multiplayer_snapshot()->'room'!='null'::jsonb then raise exception 'stale_ready_room';end if;
 perform public.dy_multiplayer_cleanup();
 if public.dy_multiplayer_snapshot()->'room'!='null'::jsonb then raise exception 'cleanup_retained_match';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',guest,'role','authenticated','is_anonymous',false)::text,true);
 begin perform public.dy_multiplayer_snapshot();raise exception 'guest_gate_bypassed';exception when others then if sqlerrm!='guests_not_ready' then raise;end if;end;
 update dy_private.mp_settings set guests_enabled=true;
 r:=public.dy_multiplayer_join('hex-fold',1);
 if r->'identity'->>'name' !~ '^Guest-[0-9]+$' or r->'identity'->>'guest'!='true' then raise exception 'guest_identity_failed';end if;
 begin perform public.dy_payment_catalog();raise exception 'guest_payment_access';exception when others then if sqlerrm!='permanent_account_required' then raise;end if;end;
 begin perform public.dy_multiplayer_privacy(true,true);raise exception 'guest_social_access';exception when others then if sqlerrm!='permanent_account_required' then raise;end if;end;
 begin perform public.dy_multiplayer_join('hex-fold',1,'global','friends');raise exception 'guest_friend_access';exception when others then if sqlerrm!='permanent_account_required' then raise;end if;end;
end $$;
rollback;
